def fibonacci_index_small(x: int) -> int:
    n = abs(x) % 20
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def f(x):
    """Returns the Fibonacci number at index abs(x), with F(0)=0 and F(1)=1."""
    if x < 0:
        x = -x
    a = 0
    b = 1
    for _ in range(x):
        a, b = b, a + b
    return a
